WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_summarize_reason'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '概括原因', 'kp-sl-summarize-reason', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "归纳概括：原因类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心心法：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "由果推因，寻找导致现象发生的深层驱动力。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、找词雷达"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“因为、由于、源于、关键在于、究其原因、与...有关”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、深浅层归类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "只看表面现象：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "比如材料写“老百姓爱吃野味导致病毒传播”。你答“老百姓爱吃野味”。对，但不全！你要继续往下找为什么爱吃？材料写了“因为缺乏科学认知和法律约束”。真正的深刻原因必须写出：【法律制度不健全】、【群众科学素养低】。申论的原因分析必须上升到制度、管理、思想层面！"}]}]}]}$$ AS jsonb), NULL, '概括原因的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "归纳概括", "概括原因"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_summarize_reason", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
